/*
 * A257881  Sequence (a(n)) generated by Rule 1 (in Comments) with a(1) = 2
 *          and d(1) = 1.
 * https://oeis.org/A257881
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 172, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: A257881
 * Recurrence: a(1)=2, d(1)=1, and
 * a(k+1)=a(k)+d(k+1) with d(k+1) chosen by Rule 1.
 * This implementation simulates Rule 1 exactly, storing the
 * sequence in static arrays that grow as needed.  It works for
 * any seq_t and idx_t where seq_t supports ordinary integer
 * arithmetic and idx_t is an unsigned 64‑bit integer. */

#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/*  Parameters for the difference hash: positive and negative values
 *  are shifted by DIFF_OFFSET before indexing a bool array.
 */
#define DIFF_OFFSET 1000000UL     /* shift for negative differences */
#define DIFF_INITIAL 2000001UL    /* DIFF_OFFSET*2+1 */

/* ------------------------------------------------------------------ */
/*  Static storage for the sequence and the used‑value tables.  They
 *  grow automatically.  All allocations are cast for C++ compliance.
 */
static seq_t *A            = NULL;      /* a[k], 1‑based */
static int64_t *D          = NULL;      /* d[k], 1‑based, signed */
static idx_t  computed     = 0;         /* last computed index */
static idx_t  capacity     = 0;         /* allocated capacity for A & D */

static bool *used_a   = NULL;          /* membership test for a‑values */
static size_t used_a_cap = 0;           /* size of used_a array */

static bool *used_diff = NULL;          /* membership test for d‑values */
static size_t used_diff_cap = 0;        /* size of used_diff array */

/* ------------------------------------------------------------------ */
/*  Resize used_a array to at least new_cap elements.  Elements beyond
 *  the current usage are initialized to false.  The old array is freed.
 */
static void ensure_used_a_size(size_t new_cap) {
    if (new_cap <= used_a_cap) return;
    size_t cap = used_a_cap ? used_a_cap * 2 : 64;
    while (cap < new_cap) cap <<= 1;
    bool *new_arr = (bool *)calloc(cap, sizeof(bool));
    memcpy(new_arr, used_a, used_a_cap * sizeof(bool));
    free(used_a);
    used_a   = new_arr;
    used_a_cap = cap;
}

/* ------------------------------------------------------------------ */
/*  Resize used_diff array to at least new_cap elements.  Elements
 *  beyond the current usage are initialized to false.  The old array
 *  is freed.
 */
static void ensure_used_diff_size(size_t new_cap) {
    if (new_cap <= used_diff_cap) return;
    size_t cap = used_diff_cap ? used_diff_cap * 2 : DIFF_INITIAL;
    while (cap < new_cap) cap <<= 1;
    bool *new_arr = (bool *)calloc(cap, sizeof(bool));
    memcpy(new_arr, used_diff, used_diff_cap * sizeof(bool));
    free(used_diff);
    used_diff = new_arr;
    used_diff_cap = cap;
}

/* ------------------------------------------------------------------ */
/*  Resize A and D arrays to hold at least need elements (1‑based).
 */
static void ensure_capacity(idx_t need) {
    if (need <= capacity) return;
    idx_t cap = capacity ? capacity * 2 : 16;
    while (cap < need) cap <<= 1;
    seq_t *newA = (seq_t *)realloc(A, (cap + 1) * sizeof(seq_t));
    int64_t *newD = (int64_t *)realloc(D, (cap + 1) * sizeof(int64_t));
    A = newA;   D = newD;
    capacity = cap;
}

/* ------------------------------------------------------------------ */
/*  Initialise the sequence with a(1)=2, d(1)=1 and set up the used‑value
 *  tables.
 */
static void init_sequence(void) {
    computed  = 1;
    capacity  = 16;
    A = (seq_t *)malloc((capacity + 1) * sizeof(seq_t));
    D = (int64_t *)malloc((capacity + 1) * sizeof(int64_t));

    A[1] = (seq_t)2;      /* a(1)=2 */
    D[1] =  1;            /* d(1)=1 */

    /* used_a */
    used_a_cap = 64;
    used_a = (bool *)calloc(used_a_cap, sizeof(bool));
    ensure_used_a_size((size_t)A[1] + 1);
    used_a[(size_t)A[1]] = true;

    /* used_diff */
    used_diff_cap = DIFF_INITIAL;
    used_diff = (bool *)calloc(used_diff_cap, sizeof(bool));
    /* d(1)=1 has positive offset */
    used_diff[(size_t)(1 + DIFF_OFFSET)] = true;
}

/* ------------------------------------------------------------------ */
/*  Main user function.  Generates the sequence on demand and returns
 *  a(n).  The function is thread‑unsafe but meets the requirements
 *  of arbitrary order of calls.
 */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;       /* protect offset <1 */

    if (!A) init_sequence();           /* first call */

    if (n > capacity) ensure_capacity(n);

    /* Generate terms up to n */
    while (computed < n) {
        seq_t a_prev = A[computed];
        /* --- Step 1: try a negative difference if possible --- */
        bool found = false;
        int64_t chosen_h = 0;
        /* a_prev is unsigned seq_t; cast to signed for range calculation */
        int64_t a_prev_signed = (int64_t)a_prev;
        int64_t lower = 1 - a_prev_signed;   /* smallest allowed h */
        for (int64_t cand = -1; cand >= lower; --cand) {
            /* check membership of h itself */
            size_t diff_idx = (size_t)(cand + DIFF_OFFSET);
            ensure_used_diff_size(diff_idx + 1);
            if (used_diff[diff_idx]) continue;

            /* new_val = a_prev + cand (cand <=-1) */
            seq_t new_val;
            if (cand < 0) {
                seq_t sub = (seq_t)(-cand);   /* |-cand| <= a_prev */
                new_val = a_prev - sub;
            } else {
                new_val = a_prev + (seq_t)cand;
            }
            /* check if new_val already used */
            size_t val_idx = (size_t)new_val;
            ensure_used_a_size(val_idx + 1);
            if (used_a[val_idx]) continue;

            chosen_h = cand;
            found = true;
            break;
        }

        if (found) { /* accepted the negative h */
            ++computed;
            D[computed] = chosen_h;
            A[computed] = (chosen_h < 0)
                ? a_prev - (seq_t)(-chosen_h)
                : a_prev + (seq_t)chosen_h;

            used_diff[(size_t)(chosen_h + DIFF_OFFSET)] = true;
            size_t val_idx = (size_t)A[computed];
            ensure_used_a_size(val_idx + 1);
            used_a[val_idx] = true;
            continue;   /* look again for another negative step */
        }

        /* --- Step 2: find the smallest positive h --- */
        int64_t hpos = 1;
        seq_t new_val;
        while (1) {
            size_t diff_idx = (size_t)(hpos + DIFF_OFFSET);
            ensure_used_diff_size(diff_idx + 1);
            if (!used_diff[diff_idx]) {
                new_val = a_prev + (seq_t)hpos;
                size_t val_idx = (size_t)new_val;
                ensure_used_a_size(val_idx + 1);
                if (!used_a[val_idx]) break;
            }
            ++hpos;
        }

        ++computed;
        D[computed] = hpos;
        A[computed] = new_val;
        used_diff[(size_t)(hpos + DIFF_OFFSET)] = true;
        size_t val_idx = (size_t)new_val;
        ensure_used_a_size(val_idx + 1);
        used_a[val_idx] = true;
    }

    return A[n];
}
